import {activeRegency} from './narrative-succession-state.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function regencyLabel(state,c){const t=activeRegency(state,c.region);if(t?.rulerId===c.id)return `<p class="regency-status">Titular ruler · Acting adult regent: ${esc(state.narrative.characters[t.regentId].name)}. Regency ends only at a recorded event.</p>`;const acting=(state.narrative.regencies||[]).find(t=>!t.end&&t.regentId===c.id);return acting?`<p class="regency-status">Acting regent for ${esc(state.narrative.characters[acting.rulerId].name)} · ${esc(acting.region)}. The titular seat belongs to that ruler.</p>`:'';}
export function successionHistoryHTML(state,c){const n=state.narrative,rows=(n.successionRecords||[]).filter(r=>[r.incumbentId,r.successorId,r.regentId].includes(c.id));return rows.length?`<section class="succession-history"><h4>Recorded succession — synthetic tests</h4>${rows.map(r=>{const t=n.regencies?.find(t=>t.successionId===r.id);return `<details><summary>Turn ${r.origin.turn} · ${esc(r.region)} · ${esc(n.characters[r.incumbentId].name)} → ${esc(n.characters[r.successorId].name)}</summary><p>SYNTHETIC TEST ONLY · ${esc(r.exit)} · ${esc(r.politicalKind)}. Source: ${esc(r.origin.source.incidentId)}.</p>${t?`<p>Titular ruler: ${esc(n.characters[t.rulerId].name)}. Acting regent: ${esc(n.characters[t.regentId].name)}${t.end?' · ended at '+esc(t.end.source.incidentId):' · continuing'}.</p>`:''}<p>Claim: ${esc(r.claimId)}. Selection was ${r.request.choice?'explicitly test-controlled':'unambiguous under the saved test policy'}.</p><ul>${r.evidence.map(e=>`<li>${esc(e.kind)} · ${esc(e.id||e.region)}${e.origin?' · '+esc(e.origin.source.incidentId||'Explicit setup'):''}</li>`).join('')}</ul>${r.privateOutlookBefore?`<details><summary>Archived private assessment — former ruler only</summary><p>${esc(n.characters[r.incumbentId].name)}: ${esc(r.privateOutlookBefore.text)}</p><p>Not inherited by the successor or public character knowledge.</p></details>`:''}</details>`;}).join('')}</section>`:'';}
